    reps = [RGA(f"r{i}") for i in range(n)]
    def gossip():
        for _ in range(rnd.randint(1, 4)):
            i, j = rnd.sample(range(n), 2)
            snap = json.loads(json.dumps(reps[i].snapshot()))
            reps[j].merge(wr(snap))
            if rnd.random() < 0.3:
                reps[j].merge(wr(snap))
    chars = list("abcxyz")
    for step in range(500):
        r = reps[rnd.randrange(n)]
        vals = r.values()
        if vals and rnd.random() < 0.4:
            idx = rnd.randrange(len(vals))
            assert r.delete(idx) == vals[idx]
        else:
            idx = rnd.randrange(len(vals) + 1)
            ch = rnd.choice(chars)
            r.insert(idx, ch)
            assert r.values()[idx] == ch
        if step % rnd.randint(1, 7) == 0:
            gossip()
    for _ in range(6):
        order = list(range(n)); rnd.shuffle(order)
        for i in order:
            for j in order:
                if i != j:
                    reps[j].merge(wr(reps[i].snapshot()))
